head.script:
// 전역 변수 초기화
scwin.LOGIN_USER_ID = "";
scwin.PJT_ID = "";

/**
 * @method
 * @name scwin.onpageload
 * @description
 * @example
 * scwin.onpageload();
 */
scwin.onpageload = function () {
    var usrId = $p.getComponentById("mf_pg_header").getWindow().scwin.USER_ID; // 헤더에서 조회
    var selPjtId = $p.getParentWindow().scwin.SEL_PJT_ID; // 메인 페이지에서 조회
    if (usrId && selPjtId) {
        scwin.LOGIN_USER_ID = usrId;
        scwin.PJT_ID = selPjtId;
    }

    // 검색 조건 초기화
    dmp_wbsVo.set("pjtId", scwin.PJT_ID);
    // WBS 조회
    scwin.btn_search_onclick();
};

/**
 * 조회 버튼 클릭 이벤트
 * @date
 * @memberOf
 * @param 
 * @returns
 * @author 
 * @example
 */
scwin.btn_search_onclick = function (e) {

    // PGAE번호 초기화
    dmp_wbsVo.set("pageIndex", "1");
    pgl_wbsList.setSelectedIndex(1);

    // 서버통신 - WBS 조회
    $c.sbm.execute(sbm_selectWbsVoList);
};

/**
 * 페이지 번호 클릭 이벤트
 * @date
 * @memberOf
 * @param 
 * @returns 
 * @author 
 * @example
 */
scwin.pgl_wbsList_onclick = function (idx) {

    // 페이지 번호 세팅
    dmp_wbsVo.set("pageIndex", idx);
    // 서버통신 - 사원목록 조회
    $c.sbm.execute(sbm_selectWbsVoList);
};

/**
 * 업무 구분명 반환 함수
 * @param {string} isDesign - 업무 구분 (0: 개발, 1: 설계)
 * @returns {string} 업무 구분명
 */
scwin.getTaskTypeName = function (isDesign) {
    if (isDesign === "1" || isDesign === 1) {
        return "설계";
    } else if (isDesign === "0" || isDesign === 0) {
        return "개발";
    } else {
        return "미분류";
    }
};

/**
 * 기존 서브미션 완료 함수 수정
 * 데이터 로드 완료 후 자동으로 업무 구분별 그룹핑 적용
 */
scwin.sbm_wbsList_submitdone = function (e) {
    // error 수신시
    var elData = e.responseJSON.elData;
    var elHeader = e.responseJSON.elHeader;
    if (elHeader == null || elHeader == "" || elHeader == "undefiend" || elHeader.resSuc == false) {
        $c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
        return false;
    }

    // WBS dataMap 초기화
    dmp_wbsVoDetail.setEmptyValue();

    // 총 레코드 수 업데이트
    spn_listCnt.setLabel(elData.totalCount);

    // 데이터에 업무 구분명 추가 및 그룹핑을 위한 필드 추가
    var wbsDataWithTaskType = elData.wbsVoList.map(function (item) {

        // 업무 구분으로 업무 구분명 조회하여 추가
        item.taskTypeName = scwin.getTaskTypeName(item.isDesign);

        // 그룹핑을 위한 업무 구분 정보 필드 (순서를 위해 isDesign 사용, 표시를 위해 taskTypeName 사용)
        item.taskTypeForGrouping = item.isDesign + '|' + item.taskTypeName; // '1|설계업무' 같은 형태

        // 지연여부 계산 추가
        const delayStatus = scwin.calculateDelayStatus(item.taskEt, item.taskRet, item.taskStatus);
        item.isLazy = scwin.getDelayStatusText(delayStatus);
        item.delayStatusCode = delayStatus; // 스타일링용

        // 테스트여부 표시용 데이터 생성 
        item.isTestDisplay = scwin.getTestStatusDisplay(item.isTest);
        item.isTestCode = item.isTest; // 스타일링용

        // 업무 구분 표시용 데이터 생성
        item.isDesignDisplay = scwin.getTaskTypeDisplay(item.isDesign);
        item.isDesignCode = item.isDesign; // 스타일링용

        return item;
    });

    dlt_wbsVoList.setJSON(wbsDataWithTaskType);

    // 페이지 네비게이터 업데이트
    var totalPageCount = Math.ceil(elData.totalCount / dmp_wbsVo.get("pageSize"));
    pgl_wbsList.setCount(totalPageCount);

    // 페이징 정보 업데이트
    spn_totalPageCount.setValue(totalPageCount);
    spn_pageIndex.setValue(dmp_wbsVo.get("pageIndex"));
    pgl_wbsList.setSelectedIndex(dmp_wbsVo.get("pageIndex"));

    // 순번 업데이트
    let num = Number(dmp_wbsVo.get("pageIndex"));
    num = (num - 1) * 10;
    grd_list.setStartRowNumber(num);

    // 진척률 컬럼 스타일 적용
    scwin.setProgressStyle();

    // 업무상태 컬럼 스타일 적용
    scwin.setTaskStatusStyle();

    // 테스트여부 컬럼 스타일 적용
    scwin.setTestStatusStyle();

    // 지연여부 컬럼 스타일 적용
    scwin.setDelayStatusStyle();

    // 업무 구분 컬럼 스타일 적용
    scwin.setTaskTypeStyle();
};

/**
 * 업무 구분별 그룹핑 함수
 */
scwin.groupByTaskType = function () {
    var options = {
        sortIndex: ["taskTypeName"],     // taskTypeName으로 정렬
        sortOrder: [1],      // 오름차순 (설계업무 -> 개발업무)
        closeGroup: false,
        groupbyHeader: [
            {
                inputType: "expression",
                // 업무 구분별 그룹 헤더 - 업무 구분명으로 표시
                expression: 'toggle() + depthStr() + " (" + count() + " 건) "',
                align: "left",
                colSpan: "18"
            }
        ],
        hideFooter: true
    };

    // 그룹핑 실행
    grd_list.groupby(options);
};

/**
 * 업무상태별 그룹핑 함수
 */
scwin.groupByTaskStatus = function () {
    var options = {
        sortIndex: ["taskStatus"], // taskStatus 컬럼으로 정렬
        sortOrder: [1],      // 오름차순
        closeGroup: false,
        groupbyHeader: [
            {
                inputType: "expression",
                expression: 'toggle() + depthStr() + " (" + count() + " 건) "',
                align: "left",
                colSpan: "18"
            }
        ],
        hideFooter: true
    };
    grd_list.groupby(options);
};

/**
 * 지연여부별 그룹핑 함수
 */
scwin.groupByDelayStatus = function () {
    var options = {
        sortIndex: ["isLazy"], // isLazy 컬럼으로 정렬
        sortOrder: [1],      // 오름차순
        closeGroup: false,
        groupbyHeader: [
            {
                inputType: "expression",
                expression: 'toggle() + depthStr() + " (" + count() + " 건) "',
                align: "left",
                colSpan: "18"
            }
        ],
        hideFooter: true
    };
    grd_list.groupby(options);
};

// 그룹바이 초기화
scwin.btn_clearGroupby_onclick = function (e) {
    grd_list.clearGroupby();

    // 검색 조건 초기화
    dmp_wbsVo.setEmptyValue();    
    dmp_wbsVo.set("pjtId", scwin.PJT_ID);
    // WBS 조회
    scwin.btn_search_onclick();
};

/**
 * 팝업을 화면 중앙에 위치시키기 위한 좌표를 계산합니다.
 * @param {number} popupWidth - 팝업의 너비 (px)
 * @param {number} popupHeight - 팝업의 높이 (px)
 * @returns {{left: string, top: string}} - 팝업의 left, top 스타일 값
 */
scwin.getCenteredPopupPosition = function (popupWidth, popupHeight) {
    const scrollX = window.scrollX || document.documentElement.scrollLeft;
    const scrollY = window.scrollY || document.documentElement.scrollTop;
    const viewportWidth = window.innerWidth || document.documentElement.clientWidth;
    const viewportHeight = window.innerHeight || document.documentElement.clientHeight;

    const left = scrollX + (viewportWidth - popupWidth) / 2;
    const top = scrollY + (viewportHeight - popupHeight) / 2;

    return { left: left + "px", top: top + "px" };
};

scwin.btn_new_onclick = function (e) {
    var popupData = {
        "type": "json",
        "name": "params",
        "data": {
            "pjtId": scwin.PJT_ID,
            "userId": scwin.LOGIN_USER_ID,
            "popupType": "new"
        }
    };

    const popupWidth = 800;
    const popupHeight = 800;
    const centeredPosition = scwin.getCenteredPopupPosition(popupWidth, popupHeight);

    const options = {
        id: "wbs_new",
        type: "wframePopup",
        width: popupWidth + "px",
        height: popupHeight + "px",
        top: centeredPosition.top,
        left: centeredPosition.left,
        popupName: "업무 생성",
        modal: true,
        closeAction: "scwin.popup_closeAction",
        dataObject: popupData
    };

    $p.openPopup("/InsWebApp/ui/wbs/WbsDetail.xml", options);
};

scwin.grd_list_oncellclick = function (rowIndex, columnIndex, columnId) {

};

/**
 * @method
 * @name scwin.popup_closeAction
 * @description 팝업 닫기 시 재조회 처리
 * @param {String} argRuntimeID - 팝업의 실행 ID
 * @param {Object} argJsnInfo - 팝업 닫힘 시 전달된 정보
 * @returns {Boolean} 팝업 닫기 여부
 */
scwin.popup_closeAction = function (argRuntimeID, argJsnInfo) {
    var popObj = $p.getPopupWindow(argRuntimeID);
    scwin.btn_search_onclick();
    return true;
};

// 그리드 셀 더블클릭 이벤트
scwin.grd_list_oncelldblclick = function (rowIndex, columnIndex, columnId) {

    var rowData = dlt_wbsVoList.getRowJSON(rowIndex);
    var popupData = {
        "type": "json",
        "name": "params",
        "data": {
            "pjtId": scwin.PJT_ID,
            "popupType": "detail",
            "rowData": rowData
        }
    };

    const popupWidth = 800;
    const popupHeight = 800;
    const centeredPosition = scwin.getCenteredPopupPosition(popupWidth, popupHeight);

    const options = {
        id: "wbs_detail",
        type: "wframePopup",
        width: popupWidth + "px",
        height: popupHeight + "px",
        top: centeredPosition.top,
        left: centeredPosition.left,
        popupName: "업무 상세",
        modal: true,
        closeAction: "scwin.popup_closeAction",
        dataObject: popupData
    };

    $p.openPopup("/InsWebApp/ui/wbs/WbsDetail.xml", options);
};

// 삭제 버튼 클릭 이벤트
scwin.btn_delete_onclick = function (e) {
    let chkArrIdx = grd_list.getCheckedIndex("chk");
    dlt_wbsVoList.deleteRows(chkArrIdx);
};

// 저장 버튼 클릭 이벤트
scwin.btn_save_onclick = function (e) {
    let reqObj = {
        "elData": { "wbsVoList": dlt_wbsVoList.getModifiedJSON() }
    };
    $c.sbm.execute(sbm_saveWbsVoList, reqObj);
};

/**
 * @method
 * @name scwin.setProgressStyle
 * @description 진행률 컬럼(taskRate)에 동적으로 배경 스타일 및 정렬 등을 적용한다.
 * @memberOf scwin
 * @date 2025.07.06
 */
scwin.setProgressStyle = function () {
    const rowCount = dlt_wbsVoList.getRowCount();
    const colIndex = grd_list.getColumnIndex("taskRate");

    for (let i = 0; i < rowCount; i++) {
        const percent = parseInt(dlt_wbsVoList.getCellData(i, "taskRate"), 10) || 0;

        let styleValue = "#ffffff";
        if (percent > 0) {
            styleValue = `linear-gradient(to right,
                #0062ff 0%,
                #3399ff ${percent}%,
                #ffffff ${percent}%,
                #ffffff 100%)`;
        }

        const styles = [
            { type: "cell", rowIndex: i, colIndex, styleName: "background", styleValue },
            { type: "cell", rowIndex: i, colIndex, styleName: "border-radius", styleValue: "10px" },
            { type: "cell", rowIndex: i, colIndex, styleName: "text-align", styleValue: "center" },
            { type: "cell", rowIndex: i, colIndex, styleName: "color", styleValue: "#000" }
        ];

        styles.forEach(style => grd_list.setStyleAll(style));
    }
};

// 다건 저장 서브미션 콜백
scwin.sbm_saveWbsVoList_submitdone = function (e) {
    var elHeader = e.responseJSON.elHeader;

    if (elHeader == null || elHeader === "" || elHeader === "undefiend" || elHeader.resSuc == false) {
        $c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
        return false;
    }

    $c.win.alert("통합 수정되었습니다.");
    scwin.btn_search_onclick();
};

// 다운로드 버튼 이벤트
scwin.btn_down_onclick = function (e) {
    // 전체 건수 확인
    var totalCount = spn_listCnt.getLabel();

    if (totalCount === "0") {
        $c.win.alert("다운로드할 데이터가 없습니다.");
        return;
    }

    // 현재 페이징 조건 백업
    var originalPageIndex = dmp_wbsVo.get("pageIndex");
    var originalPageSize = dmp_wbsVo.get("pageSize");

    // 전체 데이터 조회를 위한 조건 설정
    dmp_wbsVo.set("pageIndex", "1");
    dmp_wbsVo.set("pageSize", totalCount); // 전체 건수만큼 설정

    // 전체 데이터 조회 실행
    $c.sbm.execute(sbm_selectWbsVoListForExcel);

    // 원래 페이징 조건 복원
    dmp_wbsVo.set("pageIndex", originalPageIndex);
    dmp_wbsVo.set("pageSize", originalPageSize);
};

// 엑셀 다운로드용 전체 데이터 조회 완료 후 처리
scwin.sbm_selectWbsVoListForExcel_submitdone = function (e) {
    var elData = e.responseJSON.elData;
    var elHeader = e.responseJSON.elHeader;

    if (elHeader == null || elHeader == "" || elHeader == "undefined" || elHeader.resSuc == false) {
        $c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
        return false;
    }

    // 전체 데이터가 없는 경우
    if (!elData.wbsVoList || elData.wbsVoList.length === 0) {
        $c.win.alert("다운로드할 데이터가 없습니다.");
        return;
    }

    // 임시로 그리드에 전체 데이터 설정
    var originalData = dlt_wbsVoList.getAllJSON();
    // 데이터에 업무 구분명 추가                                                                                                                                                             
    var wbsDataForExcel = elData.wbsVoList.map(function (item) {
        item.taskTypeName = scwin.getTaskTypeName(item.isDesign);
        return item;
    });
    dlt_wbsVoList.setJSON(wbsDataForExcel);

    // 엑셀 다운로드 실행
    var options = {
        fileName: "WBS_목록_" + new Date().toISOString().slice(0, 10).replace(/-/g, ""),
        useStyle: true,
        headerFontBold: true,
        bodyFontBold: false,
        type: 1, // inputType이 "select", "autoComplete", 혹은 "checkcombobox"인 경우 >> label 값 다운
        trim: 1,
        removeColumns: "0,1,2,4,7,9,14,17,18,21,22",
        processMsg: "엑셀 파일을 생성하고 있습니다...",
        timeout: 60000,
        checkInterval: 1000,
        onSuccessCallback: function () {
            $c.win.alert("엑셀 파일 다운로드가 완료되었습니다.");
            // 원래 데이터로 복원
            dlt_wbsVoList.setJSON(originalData);
            scwin.btn_search_onclick();
        },
        onFailureCallback: function () {
            $c.win.alert("엑셀 파일 다운로드에 실패했습니다.");
            // 원래 데이터로 복원
            dlt_wbsVoList.setJSON(originalData);
            scwin.btn_search_onclick();
        }
    };

    grd_list.advancedExcelDownload(options);
};

/**
 * 개선된 지연여부 계산 함수 (실제완료일 우선 처리)
 * @param {String} taskEt - 완료예정일 (YYYY-MM-DD 형식)
 * @param {String} taskRet - 실제완료일 (YYYY-MM-DD 형식)  
 * @param {String} taskStatus - 업무상태 (진행중, 대기, 완료)
 * @returns {Number} 지연여부 (-1: 없음, 0: 완료, 1: 지연완료, 2: 지연중, 3: 진행중)
 */
scwin.calculateDelayStatus = function (taskEt, taskRet, taskStatus) {
    // 1. 완료예정일이 없는 경우
    if (!taskEt || taskEt.trim() === '') {
        return -1; // 없음
    }

    const today = new Date();
    const expectedDate = new Date(taskEt);

    // 시간 부분 제거 (날짜만 비교)
    today.setHours(0, 0, 0, 0);
    expectedDate.setHours(0, 0, 0, 0);

    // 2. 실제완료일이 있는 경우 (업무상태와 관계없이 완료된 것으로 처리)
    if (taskRet && taskRet.trim() !== '') {
        const actualDate = new Date(taskRet);
        actualDate.setHours(0, 0, 0, 0);

        if (actualDate > expectedDate) {
            return 1; // 지연완료 (실제완료일이 완료예정일보다 늦음)
        } else {
            return 0; // 완료 (실제완료일이 완료예정일과 같거나 빠름)
        }
    }

    // 3. 실제완료일이 없고 업무상태가 '완료'인 경우
    if (taskStatus === '완료') {
        // 완료 상태인데 실제완료일이 없는 경우
        return 0; // 완료로 처리
    }

    // 4. 실제완료일이 없고 업무상태가 '완료'가 아닌 경우 (진행중, 대기)
    if (today > expectedDate) {
        return 2; // 지연중 (현재날짜가 완료예정일을 지났는데 아직 완료되지 않음)
    } else {
        return 3; // 진행중 (아직 완료예정일 전이므로 정상 진행)
    }
};

/**
 * 개선된 지연여부 텍스트 반환
 */
scwin.getDelayStatusText = function (delayStatus) {
    switch (delayStatus) {
        case -1: return '없음';
        case 0: return '완료';
        case 1: return '지연완료';
        case 2: return '지연중';
        case 3: return '진행중';
        default: return '없음';
    }
};

/**
 * 개선된 지연여부 컬럼 스타일 적용
 */
scwin.setDelayStatusStyle = function () {
    const rowCount = dlt_wbsVoList.getRowCount();
    const colIndex = grd_list.getColumnIndex("isLazy");

    if (colIndex === -1) {
        console.error("isLazy 컬럼을 찾을 수 없습니다.");
        return;
    }

    for (let i = 0; i < rowCount; i++) {
        // 숫자형으로 확실히 변환
        const delayStatusCode = parseInt(dlt_wbsVoList.getCellData(i, "delayStatusCode"), 10);
        const isLazyText = dlt_wbsVoList.getCellData(i, "isLazy") || "";

        let textColor = "#6c757d"; // 기본 색상

        // 개선된 색상 분류
        if (delayStatusCode === -1) {
            textColor = "#6c757d"; // 회색 - 없음
        } else if (delayStatusCode === 0) {
            textColor = "#155724"; // 녹색 - 완료
        } else if (delayStatusCode === 1) {
            textColor = "#721c24"; // 진한 빨간색 - 지연완료 (가장 심각)
        } else if (delayStatusCode === 2) {
            textColor = "#dc3545"; // 빨간색 - 지연중
        } else if (delayStatusCode === 3) {
            textColor = "#0c5460"; // 파란색 - 진행중
        }

        const styles = [
            { type: "cell", rowIndex: i, colIndex, styleName: "color", styleValue: textColor },
            { type: "cell", rowIndex: i, colIndex, styleName: "text-align", styleValue: "center" },
            { type: "cell", rowIndex: i, colIndex, styleName: "font-weight", styleValue: "bold" }
        ];

        styles.forEach(style => {
            try {
                grd_list.setStyleAll(style);
            } catch (e) {
                console.error("스타일 적용 실패:", e, style);
            }
        });
    }
};

/**
 * 업무상태 컬럼 스타일 적용
 */
scwin.setTaskStatusStyle = function () {
    const rowCount = dlt_wbsVoList.getRowCount();
    const colIndex = grd_list.getColumnIndex("taskStatus");

    for (let i = 0; i < rowCount; i++) {
        const taskStatus = dlt_wbsVoList.getCellData(i, "taskStatus") || "";

        let textColor = "#6c757d"; // 기본 색상

        switch (taskStatus) {
            case "완료":
                textColor = "#155724"; // 녹색 (완료)
                break;
            case "진행중":
                textColor = "#0c5460"; // 파란색 (진행중)
                break;
            case "대기":
                textColor = "#856404"; // 주황색 (대기)
                break;
            default:
                textColor = "#6c757d"; // 회색 (기본)
                break;
        }

        const styles = [
            { type: "cell", rowIndex: i, colIndex, styleName: "color", styleValue: textColor },
            { type: "cell", rowIndex: i, colIndex, styleName: "text-align", styleValue: "center" },
            { type: "cell", rowIndex: i, colIndex, styleName: "font-weight", styleValue: "bold" }
        ];

        styles.forEach(style => grd_list.setStyleAll(style));
    }
};

/**
 * 테스트여부 표시 텍스트 반환
 */
scwin.getTestStatusDisplay = function (isTest) {
    if (isTest === "0") {
        return "●"; // 빨간색 원
    } else if (isTest === "1") {
        return "●"; // 녹색 원
    } else {
        return "○"; // 빈 원
    }
};

/**
 * 테스트여부 컬럼 스타일 적용 (표시용 컬럼에 적용)
 */
scwin.setTestStatusStyle = function () {
    const rowCount = dlt_wbsVoList.getRowCount();
    const colIndex = grd_list.getColumnIndex("isTestDisplay");

    for (let i = 0; i < rowCount; i++) {
        const isTestCode = dlt_wbsVoList.getCellData(i, "isTest") || ""; // 원본 값 사용

        let textColor = "#6c757d";

        if (isTestCode === "0") {
            textColor = "#dc3545"; // 빨간색
        } else if (isTestCode === "1") {
            textColor = "#28a745"; // 녹색
        } else {
            textColor = "#6c757d"; // 회색
        }

        const styles = [
            { type: "cell", rowIndex: i, colIndex, styleName: "color", styleValue: textColor },
            { type: "cell", rowIndex: i, colIndex, styleName: "text-align", styleValue: "center" },
            { type: "cell", rowIndex: i, colIndex, styleName: "font-weight", styleValue: "bold" },
            { type: "cell", rowIndex: i, colIndex, styleName: "font-size", styleValue: "18px" }
        ];

        styles.forEach(style => grd_list.setStyleAll(style));
    }
};

/**
 * 업무 구분 표시 텍스트 반환
 */
scwin.getTaskTypeDisplay = function (isDesign) {
    if (isDesign === "1" || isDesign === 1) {
        return "설계"; // 설계업무
    } else if (isDesign === "0" || isDesign === 0) {
        return "개발"; // 개발업무
    } else {
        return "미분류";
    }
};

/**
 * 업무 구분 컬럼 스타일 적용
 */
scwin.setTaskTypeStyle = function () {
    const rowCount = dlt_wbsVoList.getRowCount();
    const colIndex = grd_list.getColumnIndex("isDesignDisplay");

    if (colIndex === -1) {
        console.error("isDesignDisplay 컬럼을 찾을 수 없습니다.");
        return;
    }

    for (let i = 0; i < rowCount; i++) {
        const isDesignCode = dlt_wbsVoList.getCellData(i, "isDesign") || ""; // 원본 값 사용

        let textColor = "#6c757d";
        let backgroundColor = "#f8f9fa";

        if (isDesignCode === "1" || isDesignCode === 1) {
            textColor = "#0c5460"; // 파란색 - 설계업무
            backgroundColor = "#e1f5fe";
        } else if (isDesignCode === "0" || isDesignCode === 0) {
            textColor = "#155724"; // 녹색 - 개발업무
            backgroundColor = "#e8f5e8";
        } else {
            textColor = "#6c757d"; // 회색 - 미분류
            backgroundColor = "#f8f9fa";
        }

        const styles = [
            { type: "cell", rowIndex: i, colIndex, styleName: "color", styleValue: textColor },
            { type: "cell", rowIndex: i, colIndex, styleName: "background-color", styleValue: backgroundColor },
            { type: "cell", rowIndex: i, colIndex, styleName: "text-align", styleValue: "center" },
            { type: "cell", rowIndex: i, colIndex, styleName: "font-weight", styleValue: "bold" },
            { type: "cell", rowIndex: i, colIndex, styleName: "border-radius", styleValue: "4px" }
        ];

        styles.forEach(style => {
            try {
                grd_list.setStyleAll(style);
            } catch (e) {
                console.error("업무 구분 스타일 적용 실패:", e, style);
            }
        });
    }
};
